import { defineConfig, mergeConfig } from 'vitest/config'
import viteConfig from './vite.config.js'

export default mergeConfig(
  viteConfig,
  defineConfig({
    test: {
      // happy-dom (not jsdom): react-router's data router builds a native
      // Request on every client-side navigation, including <Navigate>
      // redirects. jsdom shadows AbortController/AbortSignal but not
      // Request/fetch, so undici rejects the mismatched signal with
      // "TypeError: RequestInit: Expected signal ... to be an instance of
      // AbortSignal" (vitest-dev/vitest#8374, remix-run/react-router#10158).
      // happy-dom doesn't hit this.
      environment: 'happy-dom',
      setupFiles: ['./src/test/setup.ts'],
      globals: false,
    },
  }),
)

import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { defineConfig } from 'vitest/config'

const TEST_DATABASE_URL =
  process.env.TEST_DATABASE_URL ??
  'postgres://chapters:chapters@localhost:5432/chapters_test'

export default defineConfig({
  test: {
    globalSetup: './test/global-setup.ts',
    fileParallelism: false,
    env: {
      DATABASE_URL: TEST_DATABASE_URL,
      NODE_ENV: 'test',
      DATA_DIR: join(tmpdir(), 'chapters-test-data'),
      // Fake embedder's bag-of-words vectors need a looser edge threshold.
      SEMANTIC_THRESHOLD: '0.2',
      COLLAB_DEBOUNCE_MS: '150',
      CREDENTIALS_ENCRYPTION_KEY: '0'.repeat(63) + '1',
    },
  },
})

import { afterEach, describe, expect, it, vi } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import { mockJsonResponse } from './lib/api'
import App from './App'

describe('App', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('redirects to the login page when there is no session', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(mockJsonResponse(401, { error: 'unauthorized' })))

    render(<App />)

    await waitFor(() => expect(screen.getByText('Login page (Task 10)')).toBeInTheDocument())
  })
})

import { afterEach, describe, expect, it, vi } from 'vitest'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { render, screen, waitFor } from '@testing-library/react'
import { createMemoryRouter, RouterProvider } from 'react-router'
import { mockJsonResponse } from '../lib/api'
import { RequireAuth } from './RequireAuth'

function renderWithRouter(initialPath: string) {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  const router = createMemoryRouter(
    [
      {
        element: <RequireAuth />,
        children: [{ path: '/', element: <div>Protected content</div> }],
      },
      { path: '/login', element: <div>Login page</div> },
    ],
    { initialEntries: [initialPath] },
  )
  render(
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  )
}

describe('RequireAuth', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('renders the protected route when the session resolves', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        mockJsonResponse(200, { id: 'u1', email: 'a@b.com', status: 'active', role: 'member', createdAt: '2026-01-01' }),
      ),
    )

    renderWithRouter('/')

    await waitFor(() => expect(screen.getByText('Protected content')).toBeInTheDocument())
  })

  it('redirects to /login when there is no session', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(mockJsonResponse(401, { error: 'unauthorized' })))

    renderWithRouter('/')

    await waitFor(() => expect(screen.getByText('Login page')).toBeInTheDocument())
  })
})

